import base64,os,subprocess
B="/var/www/alburhan"
D={
 "artifacts/api-server/src/routes/staff.ts":"",
 "artifacts/api-server/src/routes/index.ts":"",
}
for p,b in D.items():
 f=B+"/"+p
 os.makedirs(os.path.dirname(f),exist_ok=True)
 open(f,"wb").write(base64.b64decode(b))
 print("wrote:",p.split("/")[-1])
r=subprocess.run(["pnpm","--filter","@workspace/api-server","run","build"],cwd=B,capture_output=True,text=True)
print("API Build","OK" if r.returncode==0 else "FAIL")
if r.returncode!=0: print(r.stderr[-800:])
subprocess.run(["pm2","restart","api-server"],cwd=B)
print("DONE - staff API deployed")